package com.yigongbao.backup.job;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;
/** 持久化任务的订单级和文件级进度及失败证据。 */
@Service @RequiredArgsConstructor public class JobEvidenceService {private final JobOrderMapper orders;private final JobFileMapper files;public void order(long jobId,Long sourceId,Long snapshotId,String status,Throwable failure){JobOrderEntity row=orders.selectOne(Wrappers.<JobOrderEntity>lambdaQuery().eq(JobOrderEntity::getJobId,jobId).eq(JobOrderEntity::getSourceOrderId,sourceId).last("limit 1"));if(row==null){row=new JobOrderEntity();row.setJobId(jobId);row.setSourceOrderId(sourceId);row.setSnapshotId(snapshotId);row.setStatus(status);evidence(row,failure);orders.insert(row);}else{row.setStatus(status);evidence(row,failure);orders.updateById(row);}}public void file(long jobId,Long sourceId,String identity,String step,String status,long done,long total,Throwable failure){JobFileEntity row=files.selectOne(Wrappers.<JobFileEntity>lambdaQuery().eq(JobFileEntity::getJobId,jobId).eq(JobFileEntity::getAssetIdentity,identity).eq(JobFileEntity::getStep,step).last("limit 1"));if(row==null){row=new JobFileEntity();row.setJobId(jobId);row.setSourceOrderId(sourceId);row.setAssetIdentity(identity);row.setStep(step);row.setStatus(status);row.setBytesDone(done);row.setBytesTotal(total);evidence(row,failure);files.insert(row);}else{row.setStatus(status);row.setBytesDone(done);row.setBytesTotal(total);evidence(row,failure);files.updateById(row);}}private static void evidence(JobOrderEntity row,Throwable e){row.setFailureCode(e==null?null:e.getClass().getSimpleName());row.setFailureMessage(e==null?null:safe(e));}private static void evidence(JobFileEntity row,Throwable e){row.setFailureCode(e==null?null:e.getClass().getSimpleName());row.setFailureMessage(e==null?null:safe(e));}private static String safe(Throwable e){String m=e.getMessage();return m==null?"任务项失败":m.substring(0,Math.min(1000,m.length()));}}
